package com.dataengine.governance.api;
import com.dataengine.governance.domain.*; import com.dataengine.governance.service.QualityGovernanceService; import jakarta.validation.Valid; import org.springframework.http.HttpStatus; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/v1/quality") public class QualityController {private final QualityGovernanceService service;public QualityController(QualityGovernanceService s){service=s;}@GetMapping("/rules")public List<QualityRule> rules(){return service.rules();}@PostMapping("/rules")@ResponseStatus(HttpStatus.CREATED)public QualityRule create(@Valid @RequestBody CreateQualityRuleRequest r){return service.create(r.assetQualifiedName(),r.name(),r.metric(),r.threshold(),r.severity(),r.owner());}@GetMapping("/data-changes/{id}/results")public List<QualityResult> results(@PathVariable UUID id){return service.results(id);}@PostMapping("/data-changes/{changeId}/rules/{ruleId}/evaluate")public QualityResult evaluate(@PathVariable UUID changeId,@PathVariable UUID ruleId,@Valid @RequestBody EvaluateQualityRequest r){return service.evaluate(changeId,ruleId,r.observedValue(),r.actor());}@PostMapping("/results/{id}/acknowledge")public QualityResult acknowledge(@PathVariable UUID id,@Valid @RequestBody ActionRequest r){return service.acknowledge(id,r.actor(),r.reason());}@PostMapping("/results/{id}/waive")public QualityResult waive(@PathVariable UUID id,@Valid @RequestBody ActionRequest r){return service.waive(id,r.actor(),r.reason());}@PostMapping("/results/{id}/resolve")public QualityResult resolve(@PathVariable UUID id,@Valid @RequestBody ActionRequest r){return service.resolve(id,r.actor(),r.reason());}}
